const input = $input.first().json || {};
const clienteIdRaw = String(input.cliente_id ?? '').trim();
const tecnicoId = String(input.tecnico_id ?? '').trim() || null;
const tecnicoNome = String(input.tecnico_nome ?? '').trim() || null;
const tecnicoWhatsapp = String(input.tecnico_whatsapp ?? '').trim() || null;
const conversaId = String(input.conversa_id ?? '').trim() || null;
const clienteNome = String(input.cliente_nome ?? '').trim() || null;
const observacoes = String(input.observacoes ?? '').trim() || null;
const situacaoIdRaw = String(input.situacao_id ?? '').trim();

if (!/^[0-9]+$/.test(clienteIdRaw)) {
  return [{
    json: {
      sucesso: false,
      erro: 'cliente_id validado e obrigatório e deve ser numérico. W3b nao pode seguir sem cliente confirmado.',
      cliente_id: null,
      cliente_nome: clienteNome,
      tecnico_id: tecnicoId,
      tecnico_nome: tecnicoNome,
      tecnico_whatsapp: tecnicoWhatsapp,
      conversa_id: conversaId
    }
  }];
}

const situacaoId = /^[0-9]+$/.test(situacaoIdRaw) ? parseInt(situacaoIdRaw, 10) : 6237497;

return [{
  json: {
    sucesso: true,
    cliente_id: clienteIdRaw,
    cliente_nome: clienteNome,
    tecnico_id: tecnicoId,
    tecnico_nome: tecnicoNome,
    tecnico_whatsapp: tecnicoWhatsapp,
    conversa_id: conversaId,
    observacoes,
    situacao_id: situacaoId,
    payload_criar_os: {
      cliente_id: parseInt(clienteIdRaw, 10),
      situacao_id: situacaoId,
      data: new Date().toISOString().slice(0, 10),
      observacoes: observacoes || 'OS aberta via Assistente Vanda - Piccinin Security',
      vendedor_id: 906858
    }
  }
}];

const p = $input.first().json || {};
if (p.sucesso === false || p.erro) return [{ json: p }];
return [{ json: { ...p, payload_criar_os: p.payload_criar_os } }];

const base = $('Montar Payload Criar OS').first().json || {};
const resp = $input.first().json || {};

if (base.sucesso === false || base.erro) {
  return [{
    json: {
      sucesso: false,
      erro: base.erro || 'cliente_id invalido ou ausente.',
      os_id: null,
      os_codigo: null,
      cliente_id: base.cliente_id || null,
      cliente_nome: base.cliente_nome || null,
      tecnico_id: base.tecnico_id || null,
      tecnico_nome: base.tecnico_nome || null,
      tecnico_whatsapp: base.tecnico_whatsapp || null,
      conversa_id: base.conversa_id || null
    }
  }];
}

const statusCode = Number(resp.statusCode || resp.status || resp.code || 0);
const body = resp.data || resp;
const erroMsg = resp.message || resp.error || resp.detail || null;

if ((statusCode && statusCode >= 400) || resp.status === 'error' || erroMsg) {
  return [{
    json: {
      sucesso: false,
      erro: erroMsg || ('Falha ao criar a OS no Bom Saldo (status ' + (statusCode || 'desconhecido') + ').'),
      os_id: null,
      os_codigo: null,
      cliente_id: base.cliente_id,
      cliente_nome: base.cliente_nome || null,
      tecnico_id: base.tecnico_id || null,
      tecnico_nome: base.tecnico_nome || null,
      tecnico_whatsapp: base.tecnico_whatsapp || null,
      conversa_id: base.conversa_id || null,
      payload_criar_os: base.payload_criar_os
    }
  }];
}

const osId = body.id || body.os_id || body.osId || null;
const osCodigo = body.codigo || body.os_codigo || null;

if (!osId || !osCodigo) {
  return [{
    json: {
      sucesso: false,
      erro: 'Resposta do Bom Saldo nao trouxe os campos esperados (id/codigo).',
      os_id: null,
      os_codigo: null,
      cliente_id: base.cliente_id,
      cliente_nome: base.cliente_nome || null,
      tecnico_id: base.tecnico_id || null,
      tecnico_nome: base.tecnico_nome || null,
      tecnico_whatsapp: base.tecnico_whatsapp || null,
      conversa_id: base.conversa_id || null,
      payload_criar_os: base.payload_criar_os
    }
  }];
}

return [{
  json: {
    sucesso: true,
    resultado: 'OS #' + osCodigo + ' aberta com sucesso. ID interno: ' + osId + '.',
    os_id: String(osId),
    os_codigo: String(osCodigo),
    cliente_id: base.cliente_id,
    cliente_nome: base.cliente_nome || null,
    tecnico_id: base.tecnico_id || null,
    tecnico_nome: base.tecnico_nome || null,
    tecnico_whatsapp: base.tecnico_whatsapp || null,
    conversa_id: base.conversa_id || null,
    payload_criar_os: base.payload_criar_os
  }
}];

const p = $('Formatar Resposta').first().json || {};
return [{
  json: {
    os_codigo: p.os_codigo,
    os_id_bomsaldo: p.os_id,
    cliente_codigo: p.cliente_id,
    cliente_nome: p.cliente_nome || null,
    tecnico_id: p.tecnico_id || null,
    tecnico_nome: p.tecnico_nome || null,
    tecnico_whatsapp: p.tecnico_whatsapp || null,
    conversa_id: p.conversa_id || null,
    status_os: 'aberta',
    fase_ia: 'coleta_tecnica',
    qtd_evidencias: 0,
    produtos_json: '[]',
    servicos_json: '[]'
  }
}];

const resp = $('Formatar Resposta').first().json || {};
let persisted = null;
try { persisted = $('Salvar Contexto Supabase HTTP').first().json || null; } catch {}
const persistedRow = Array.isArray(persisted) ? persisted[0] : persisted;
return [{
  json: {
    resultado: resp.resultado || resp.erro || 'Resultado indisponivel.',
    sucesso: !!resp.sucesso,
    os_id: resp.os_id || null,
    os_codigo: resp.os_codigo || null,
    cliente_id: resp.cliente_id || null,
    cliente_nome: resp.cliente_nome || null,
    persistido_no_w8: !!persistedRow,
    persistido_em_supabase: !!persistedRow,
    supabase_http: persistedRow || null
  }
}];
